-- Every `pg_constraint` column pglet models, over all five constraint kinds. The
-- constants are 18.6's for a pglet-shaped catalog and each was measured: a non-FK row's
-- `confupdtype` / `confdeltype` / `confmatchtype` are a **space** (not the empty string
-- `attidentity` uses for its own "none"), `connoinherit` is true only for PK / UNIQUE /
-- FOREIGN KEY, and a CHECK's `conkey` names the columns its predicate references.
-- `oid`, `conindid`, `conrelid` and `confrelid` are catalog identities and cannot be
-- compared across engines; `conindid <> 0` and `confrelid <> 0` pin their polarity, and
-- `connamespace` is resolved through `pg_namespace` for the same reason — the `public`
-- schema's own OID is 2200 in a fresh database and something else in one whose `public`
-- was dropped and recreated, which the fixture harness does.
-- @setup
CREATE TYPE cat_mood AS ENUM ('sad', 'ok', 'happy');
CREATE TABLE cat_parent (
  id INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  code TEXT NOT NULL,
  region VARCHAR(8) NOT NULL,
  CONSTRAINT cat_parent_code_region_uq UNIQUE (code, region)
);
CREATE TABLE cat_child (
  cid INT GENERATED BY DEFAULT AS IDENTITY,
  pid INT REFERENCES cat_parent(id) ON DELETE CASCADE,
  qty INT NOT NULL,
  label TEXT,
  price NUMERIC(10,2),
  m cat_mood,
  CONSTRAINT cat_child_qty_positive CHECK (qty > 0),
  -- Two columns, named out of position order: `conkey` is 18.6's `pull_var_clause`
  -- walk order (`{3,2}`), not the table's column order. Integer operands only —
  -- a text literal would drag in the deparser's recorded `''` vs `''::text`
  -- divergence, which is not this constraint's subject.
  CONSTRAINT cat_child_qty_pid CHECK (qty > 1 AND pid > 0)
);
CREATE INDEX cat_child_pid_idx ON cat_child (pid);
CREATE INDEX cat_child_lower_label_idx ON cat_child (lower(label));
CREATE INDEX cat_child_partial_idx ON cat_child (qty) WHERE qty > 10;
CREATE SEQUENCE cat_plain_seq START 5;

-- @test
SELECT c.conname::text AS conname, c.contype::text AS contype,
       (SELECT n.nspname::text FROM pg_namespace n WHERE n.oid = c.connamespace)
         AS conschema,
       c.condeferrable, c.condeferred, c.conenforced, c.convalidated,
       c.contypid AS contypid, c.conparentid AS conparentid,
       c.conindid <> 0 AS has_index, c.confrelid <> 0 AS has_parent,
       c.confupdtype::text AS upd, c.confdeltype::text AS del,
       c.confmatchtype::text AS matchtype,
       c.conislocal, c.coninhcount, c.connoinherit, c.conperiod,
       c.conkey::text AS conkey, c.confkey::text AS confkey
FROM pg_constraint c
JOIN pg_class cls ON cls.oid = c.conrelid
WHERE cls.relname::text IN ('cat_parent', 'cat_child')
ORDER BY conname
